// The line drawings of the TV's home screen, as SVG path data. Made from the preview of the TV's
// home screen, where they were drawn and approved.

/** How one stroke of a console's drawing is drawn. */
internal enum class StrokeKind { LINE, DETAIL, DOT, ACCENT_DOT, ACCENT, ACCENT_SECOND }

internal class ConsoleStroke(val kind: StrokeKind, val path: String)

/** A drawing of a console: its own, on a 64 by 48 box; or the kind's, on a 48 by 48 box. */
internal class ConsoleLines(val strokes: List<ConsoleStroke>, val own: Boolean)

