internal fun consoleLines(consoleId: String, drawing: ConsoleDrawing): ConsoleLines =
    OwnConsoleLines[consoleId]?.let { ConsoleLines(it, own = true) }
        ?: ConsoleLines(listOf(ConsoleStroke(StrokeKind.LINE, kindLines(drawing))), own = false)

